import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.CdvW4CUT.js";const _=JSON.parse('{"title":"伺服規定 2021-10-24","description":"","frontmatter":{},"headers":[],"relativePath":"rule/history/20211024/index.md","filePath":"rule/history/20211024.md"}'),u={name:"rule/history/20211024/index.md"};function r(o,l,n,h,c,s){return a(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="伺服規定-2021-10-24" tabindex="-1">伺服規定 2021-10-24 <a class="header-anchor" href="#伺服規定-2021-10-24" aria-label="Permalink to &quot;伺服規定 2021-10-24&quot;">​</a></h1><ul><li><h3 id="請勿影響其他玩家遊玩或伺服運作" tabindex="-1">請勿影響其他玩家遊玩或伺服運作 <a class="header-anchor" href="#請勿影響其他玩家遊玩或伺服運作" aria-label="Permalink to &quot;請勿影響其他玩家遊玩或伺服運作&quot;">​</a></h3><ul><li>破壞建築、偷東西、騷擾、詐欺、惡意誤導、無意義LAG機...等影響他人的行為。 <ul><li>基本上，在路上看到人造建築與箱子不要任意去亂碰</li></ul></li><li>嚴禁以非正當管道取得畫作 <ul><li>非正當管道係指未經作者同意逕自盜印或複製畫作</li></ul></li><li>嚴禁有任何影響伺服運作之行為或預謀 <ul><li>包含但不限於以網路或電磁紀錄等方式影響伺服運作</li><li>為確保伺服運作的穩定，此類個案的處置依據將可能溯及既往</li><li>必要時，伺服人員需向全體玩家公開判決依據及理由</li><li>若有嚴重危害而致違法疑慮者，將不排除採取法律途徑</li></ul></li><li>若有上述之情事發生，伺服人員擁有主動介入處置之權利 <ul><li>未明載但屬本項規定所涵蓋之事項，將由伺服人員認定及處置</li></ul></li></ul></li><li><h3 id="嚴禁使用任何外掛與遊戲bug" tabindex="-1">嚴禁使用任何外掛與遊戲BUG <a class="header-anchor" href="#嚴禁使用任何外掛與遊戲bug" aria-label="Permalink to &quot;嚴禁使用任何外掛與遊戲BUG&quot;">​</a></h3><ul><li>以下幾種模組可使用： <ul><li>小地圖、整理背包、光影</li><li>藍圖(Litematica)、連點 <ul><li>不可用於活動或使用腳本運行</li></ul></li><li>其餘未明載之模組若要使用，建議事先詢問客服是否允許使用</li></ul></li><li>以下模組或功能嚴禁使用(包括但不限於) <ul><li>任何具外掛或透視功能的材質包/模組</li><li>使用外掛客戶端遊玩(不論是否開啟外掛功能)</li><li>飛行、自動建設、自動戰鬥...</li></ul></li><li>遊戲BUG <ul><li>原版BUG : TNT、鐵軌、地毯複製機...</li></ul></li><li>伺服異常或插件漏洞 <ul><li>利用或從中獲取利益</li></ul></li><li>若玩家知悉上述之情事發生，請即時利用<a href="/contact/">客服</a>通報，切勿知情不報 <ul><li>知情不報者經伺服人員查獲時將一併進行處置</li></ul></li><li>若有上述之情事發生，伺服人員擁有主動介入處置之權利 <ul><li>未明載但屬本項規定所涵蓋之事項，將由伺服人員認定及處置</li></ul></li></ul></li><li><h3 id="請勿開分身或使用vpn遊玩" tabindex="-1">請勿開分身或使用VPN遊玩 <a class="header-anchor" href="#請勿開分身或使用vpn遊玩" aria-label="Permalink to &quot;請勿開分身或使用VPN遊玩&quot;">​</a></h3><ul><li>若有這類需求，請務必主動利用<a href="/contact/">客服</a>向伺服人員詢問或提出申請</li><li>違反本項規定將依照伺服人員之認定進行處置</li></ul></li></ul><h2 id="處置與上訴" tabindex="-1">處置與上訴 <a class="header-anchor" href="#處置與上訴" aria-label="Permalink to &quot;處置與上訴&quot;">​</a></h2><ul><li>違反上述伺服規定，伺服有權利對玩家進行以下的處置 <ul><li>暫停或終止玩家的遊玩權限</li><li>暫時限制玩家在遊戲聊天室發言的權利</li><li>刪除或回溯玩家的遊玩紀錄</li></ul></li><li>玩家權利上訴 <ul><li>玩家可在處分確定後由<a href="/contact/">客服</a>詢問/調解/上訴 <ul><li>上訴期限 : 判決確定後一個月內</li></ul></li></ul></li><li>處分資料 <ul><li>資料係指:處分依據與解釋判決 <ul><li>帶有個人隱私之內容需消去處理<br> (例如:IP / 座標 / 私人檢舉...)</li></ul></li><li>當事人有權利詢問與要求伺服人員提供資料<br> 而伺服人員有義務向當事人提供與解釋</li><li>雙方皆有權利向全體玩家公開資料以接受公評</li></ul></li></ul><h2 id="備註" tabindex="-1">備註 <a class="header-anchor" href="#備註" aria-label="Permalink to &quot;備註&quot;">​</a></h2><ol><li>伺服處分以帳號與IP為準，請務必保管好個人帳號(切勿外借給任何人，若發生任何狀況須自行承擔責任)，不接受任何因個人因素導致之理由作為要求解除處分之依據。</li><li>若發現有玩家有違反以上規定時，請即時利用<a href="/contact/">客服</a>，切勿知情不報。</li><li>若對於規定有任何疑慮或意見，請利用<a href="/contact/">客服</a>主動詢問伺服人員。</li><li>本規定適用範圍 : 風平浪靜 Minecraft Java 伺服器。</li></ol>',6)])])}const f=i(u,[["render",r]]);export{_ as __pageData,f as default};
